package paradox.music.nativeui;

import android.Manifest;
import android.content.Context;
import android.content.pm.PackageManager;
import android.net.ConnectivityManager;
import android.net.Network;
import android.net.NetworkCapabilities;
import android.os.Build;
import android.os.Handler;
import android.os.Looper;
import android.view.View;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.net.URI;
import java.util.*;

/** Local metadata only. Never records URLs, query strings, bodies, account names or credential values. */
public final class NativeMusicNetworkDiagnostics {
 private static final ArrayDeque<String> events=new ArrayDeque<String>();
 private static final Map<Object,String> requests=Collections.synchronizedMap(new WeakHashMap<Object,String>());
 private static volatile long began;
 private static volatile boolean shown;
 private static volatile Context app;
 private static volatile int appConnected=-1,cronetType=-1;
 private static String lastBrowse="not-observed",lastBrowseRequest="not-observed",lastBrowseResponse="not-observed",lastAuth="not-observed",lastAuthResult="not-observed",lastAccounts="not-observed",lastApi="not-observed";
 private static int started, responses, failures, authStarts, authReturns;
 private NativeMusicNetworkDiagnostics(){}
 public static synchronized void begin(Context context){app=context==null?null:context.getApplicationContext();began=android.os.SystemClock.elapsedRealtime();shown=false;events.clear();requests.clear();started=responses=failures=authStarts=authReturns=0;lastBrowse=lastBrowseRequest=lastBrowseResponse=lastAuth=lastAuthResult=lastAccounts=lastApi="not-observed";appConnected=cronetType=-1;}
 private static synchronized void event(String safe){if(began==0)return;while(events.size()>=24)events.removeFirst();String entry=(android.os.SystemClock.elapsedRealtime()-began)+"ms "+safe;events.addLast(entry);if(safe.contains(" browse")){lastBrowse=entry;if(safe.startsWith("request "))lastBrowseRequest=entry;if(safe.startsWith("response "))lastBrowseResponse=entry;}if(safe.startsWith("auth-"))lastAuth=entry;if(safe.startsWith("auth-return"))lastAuthResult=entry;if(safe.startsWith("auth-account-query"))lastAccounts=entry;if(safe.startsWith("API-error"))lastApi=entry;}
 private static Object field(Object o,String n){try{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException missing){} }catch(Throwable ignored){}return null;}
 private static Object call(Object o,String n){if(o==null)return null;try{Method m=o.getClass().getMethod(n);m.setAccessible(true);return m.invoke(o);}catch(Throwable ignored){return null;}}
 private static int number(Object o){return o instanceof Number?((Number)o).intValue():-1;}
 private static String type(Object o){if(o==null)return "none";String s=o.getClass().getName();return s.matches("[A-Za-z0-9_.$]+")?s:"unavailable-type";}
 static String endpoint(String url){try{URI u=URI.create(url);String h=u.getHost(),p=u.getPath();String host=Arrays.asList("youtubei.googleapis.com","www.youtube.com","music.youtube.com","youtube.com").contains(h)?h:"other-host";if(p!=null)for(String k:new String[]{"browse","search","player","next","log_event","get_datsync_ids","account/account_menu","navigation/resolve_url","guide"})if(p.equals("/youtubei/v1/"+k))return host+" "+k;return host+" other-path";}catch(Throwable ignored){return "unclassified-endpoint";}}
 private static String headerFlags(Object raw){boolean auth=false,cookie=false,visitor=false,client=false;if(raw instanceof Map)raw=((Map<?,?>)raw).entrySet();if(raw instanceof Iterable)for(Object e:(Iterable<?>)raw){Object k=e instanceof Map.Entry?((Map.Entry<?,?>)e).getKey():null;if(!(k instanceof String))continue;String s=(String)k;auth|=s.equalsIgnoreCase("Authorization");cookie|=s.equalsIgnoreCase("Cookie");visitor|=s.equalsIgnoreCase("X-Goog-Visitor-Id");client|=s.equalsIgnoreCase("X-Youtube-Client-Name");}return "auth-header="+auth+" cookie-header="+cookie+" visitor-header="+visitor+" client-header="+client;}
 public static void request(Object request){try{String name=request.getClass().getName(),url=null;Object headers=null;if(name.equals("org.chromium.net.impl.CronetUrlRequest")){url=(String)field(request,"n");headers=field(request,"r");}else if(name.equals("cecr")){url=(String)field(request,"m");headers=field(request,"e");}else if(name.equals("cdyp"))url=(String)field(request,"c");String safe=endpoint(url);requests.put(request,safe);synchronized(NativeMusicNetworkDiagnostics.class){started++;}event("request "+safe+" stack="+type(request)+" "+(name.equals("cdyp")?"headers=not-observed":headerFlags(headers)));}catch(Throwable ignored){}}
 public static void response(Object request,Object info){try{Object url=call(info,"getUrl");String safe=url instanceof String?endpoint((String)url):requests.get(request);int status=number(call(info,"getHttpStatusCode"));synchronized(NativeMusicNetworkDiagnostics.class){responses++;}event("response "+(safe==null?"unclassified-endpoint":safe)+" HTTP="+status+" cached="+Boolean.TRUE.equals(call(info,"wasCached")));}catch(Throwable ignored){}}
 public static void failure(Object request,Object info,Throwable error){try{if(info!=null)response(request,info);synchronized(NativeMusicNetworkDiagnostics.class){failures++;}String safe=requests.get(request);event("transport-failure "+(safe==null?"unclassified-endpoint":safe)+" "+causes(error));}catch(Throwable ignored){}}
 public static void apiError(Throwable error){try{if(error!=null)event("API-error "+causes(error));}catch(Throwable ignored){}}
 private static String causes(Throwable error){StringBuilder s=new StringBuilder();Set<Throwable> seen=Collections.newSetFromMap(new IdentityHashMap<Throwable,Boolean>());for(int i=0;error!=null&&i<5&&seen.add(error);i++,error=error.getCause()){if(i>0)s.append(" <- ");s.append(type(error));int code=number(call(error,"getErrorCode")),nativeCode=number(call(error,"getCronetInternalErrorCode"));if(code!=-1)s.append(" errorCode=").append(code);if(nativeCode!=-1)s.append(" cronetCode=").append(nativeCode);Object status=type(error).equals("ahcy")?field(error,"a"):null;Object response=field(error,"b");if(type(response).equals("ahmk"))status=field(response,"a");if(status instanceof Integer&&((Integer)status)>=100&&((Integer)status)<=599)s.append(" HTTP=").append(status);}return s.toString();}
 public static void authStart(Object account){try{synchronized(NativeMusicNetworkDiagnostics.class){authStarts++;}event("auth-start selected-account-match="+AccountBridge.matchesSelectedAccount(account));}catch(Throwable ignored){}}
 public static void authResult(Object tokenData){try{Object token=field(tokenData,"b");boolean present=token instanceof String&&!((String)token).isEmpty();synchronized(NativeMusicNetworkDiagnostics.class){authReturns++;}event("auth-return token-present="+present);}catch(Throwable ignored){}}
 public static void accounts(Object values){try{Object[] list=values instanceof Object[]?(Object[])values:new Object[0];boolean match=false;for(Object a:list)match|=AccountBridge.matchesSelectedAccount(a);event("auth-account-query count="+list.length+" selected-account-visible="+match);}catch(Throwable ignored){}}
 public static void appConnectivity(boolean value){try{int n=value?1:0;if(appConnected!=n){appConnected=n;event("Music-connectivity connected-or-connecting="+value);}}catch(Throwable ignored){}}
 public static void cronetConnectivity(int value){try{if(cronetType!=value){cronetType=value;event("Cronet-connection-type="+value);}}catch(Throwable ignored){}}
 public static void uiState(final Object view,final int state){try{if(state!=4||!(view instanceof View)||shown)return;final long session=began;final java.lang.ref.WeakReference<Object> target=new java.lang.ref.WeakReference<Object>(view);new Handler(Looper.getMainLooper()).postDelayed(()->{try{Object current=target.get();if(session!=began||shown||!(current instanceof View)||!((View)current).isShown()||number(field(current,"f"))!=4)return;shown=true;event("visible-loading-error-state");NativeMusicDiagnostics.showNetworkReport(snapshot());}catch(Throwable ignored){}},1500);}catch(Throwable ignored){}}
 public static String snapshot(){StringBuilder s=new StringBuilder("Network/auth observation, not a confirmed root cause\n");Context c=app;s.append(AccountBridge.diagnosticSummary()).append('\n');try{s.append("INTERNET permission=").append(c.checkSelfPermission(Manifest.permission.INTERNET)==PackageManager.PERMISSION_GRANTED).append(" ACCESS_NETWORK_STATE permission=").append(c.checkSelfPermission(Manifest.permission.ACCESS_NETWORK_STATE)==PackageManager.PERMISSION_GRANTED).append('\n');ConnectivityManager cm=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);Network active=cm.getActiveNetwork();NetworkCapabilities caps=cm.getNetworkCapabilities(active);s.append("active-network=").append(active!=null).append(" capabilities=").append(caps!=null);if(caps!=null)s.append(" internet=").append(caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)).append(" validated=").append(caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)).append(" cellular=").append(caps.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)).append(" wifi=").append(caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)).append(" vpn=").append(caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN));s.append(" metered=").append(cm.isActiveNetworkMetered());if(Build.VERSION.SDK_INT>=24)s.append(" background-restriction=").append(cm.getRestrictBackgroundStatus());s.append('\n');}catch(Throwable e){s.append("connectivity-snapshot-error ").append(type(e)).append('\n');}s.append("Ssl_Guard installed=").append(java.security.Security.getProvider("Ssl_Guard")!=null).append('\n');synchronized(NativeMusicNetworkDiagnostics.class){s.append("Music-connectivity-result=").append(appConnected).append(" Cronet-connection-type=").append(cronetType).append(" (-1 means not observed)\n");s.append("browse-request: ").append(lastBrowseRequest).append("\nbrowse-response: ").append(lastBrowseResponse).append("\nauth-result: ").append(lastAuthResult).append("\nauth-accounts: ").append(lastAccounts).append("\nlast-browse: ").append(lastBrowse).append("\nlast-auth: ").append(lastAuth).append("\nlast-api-error: ").append(lastApi).append("\n");s.append("requests-started=").append(started).append(" responses=").append(responses).append(" transport-failures=").append(failures).append(" auth-starts=").append(authStarts).append(" auth-returns=").append(authReturns).append('\n');for(String e:events)s.append(e).append('\n');}s.append("No credentials, account names, raw URLs, headers, bodies or exception messages recorded. No observed browse request is not proof of no network activity.\n");return s.toString();}
}
